from pathlib import Path
p=Path('apps/web/src/alpha-app.tsx')
s=p.read_text(encoding='utf-8')
s=s.replace('[panel,setPanel]=useState<','[panel,updatePanel]=useState<',1)
anchor=" const openHud=(next:"
insert=""" const managementTrigger=useRef<HTMLElement|null>(null),[journalTab,setJournalTab]=useState<'overview'|'projects'|'future'|'ledger'>('overview');
 const setPanel=(next:typeof panel)=>{if(next==='studio'||next==='journal'){const active=document.activeElement as HTMLElement|null;managementTrigger.current=active?.closest('.studio-dock')?active:moreTrigger.current;}updatePanel(next);};
 const closeDrawer=()=>{const management=panel==='studio'||panel==='journal';setPanel(null);if(management)requestAnimationFrame(()=>{if(!document.querySelector('dialog[open]'))(managementTrigger.current??moreTrigger.current)?.focus({preventScroll:true});});};
"""
assert s.count(anchor)==1
s=s.replace(anchor,insert+anchor)
s=s.replace('route={panel} close={()=>setPanel(null)}','route={panel} close={closeDrawer}',1)
start=s.index(" {panel==='studio'&&")
end=s.index(' {view.bankrupt&&',start)
s=s[:start]+""" {panel==='studio'&&<div class="management-content">
 <p class="management-intro">{tr('先看资金与目标，再决定下一笔投入。','Check funds and goals before your next investment.')}</p>
 <div class="finance-summary"><span>{tr('净偿付资金','Net solvency')}</span><b>¥{view.liquidCash.toFixed(0)}</b><p>{tr('下次周结','Next weekly bill')} ¥{view.nextWeeklyBill.toFixed(0)} · {tr('贷款本金','Loan principal')} ¥{view.loan}</p></div>
 {view.office&&<section class="management-card"><h3>{tr('工作站与布置','Stations and layout')}</h3><p>{tr('已配置工位','Configured stations')} {view.office.capacity.work} · {tr('家具与升级在布置中管理。','Manage furniture and upgrades in Arrange office.')}</p><button disabled={locked} onClick={()=>{setHud(null);setPanel(null);setArranging(true);}}><Icon name="decor"/>{tr('布置办公室','Arrange office')}</button>{locked&&<small>{tr('请先完成当前操作或处理经营状态。','Finish the current operation or resolve the studio state first.')}</small>}</section>}
 <details class="management-card" open><summary>{tr('第','Chapter ')} {p.chapter} · {chapterTitles[p.chapter]}</summary><ul class="chapter-goals">{view.chapterGoal.requirements.map(r=><li key={r.id??r.label}>{r.met?'✓':'○'} {tr(r.label,r.labelEn)} · {r.current.toFixed(Number.isInteger(r.current)?0:2)} / {r.target}</li>)}</ul><p class="management-caption">{tr('第0章目标','Chapter 0 goal')}: {tr({pending:'待结算',passed:'达成',missed:'可继续经营后补达成'}[p.chapterZero],p.chapterZero)} · {tr('已完成章节','Completed chapters')}: {p.completed.join(', ')||'—'}</p><button disabled={locked||!view.chapterGoal.ready} onClick={()=>life('chapter','next')}>{p.chapter===1?tr('举行融资路演，进入第2章','Hold the pitch and enter chapter 2'):tr('确认章节目标','Complete chapter goal')}</button>{!view.chapterGoal.ready&&<small>{tr('完成上方所有目标后可确认。','Complete every goal above before confirming.')}</small>}<details><summary>{tr('玩法提示','How to play')}</summary><p>{tr('先读委托，再澄清、接单、派遣。晚上可去食堂吃饭、图书馆学习，或和伙伴聊天。每人每槽一次活动。每7天付账，14天结算旧债。','Read, clarify, accept and assign. In the evening, eat at the canteen, study in the library or chat. Each character has one activity per slot. Bills arrive weekly; inherited debt is due on day 14.')}</p></details></details>
 <details class="management-card"><summary>{tr('客户项目进度','Client project progress')}</summary><ProjectPanel view={view} english={english} busy={locked} send={send} openJob={setJobId}/></details>
 <details class="management-card"><summary>{tr('伙伴招募与人手','Recruitment and staffing')}</summary><p class="management-caption">{tr('在岗伙伴','Recruited teammates')} {view.actors.length} · {tr('人手相关周结费用已计入上方账单；招募条件与一次性费用如下。','Staffing costs are included in the weekly bill above; requirements and one-time recruitment fees follow.')}</p><div class="management-list">{catalog.recruits.filter(r=>!view.actors.some(a=>a.id===r.character)).map(r=><article class="management-row" key={r.character}><div><b>{names[r.character]}</b><small>¥{r.cost} · {tr('声望','Reputation')} {r.reputation} · {tr('第','Chapter ')} {r.minChapter??0}{tr('章开放',' unlock')}</small><small>{locked?tr('请先处理当前状态','Resolve the current state first'):p.chapter<(r.minChapter??0)?tr('章节尚未开放','Chapter not unlocked'):view.cash<r.cost?tr('现金不足','Not enough cash'):view.reputation<r.reputation?tr('声望不足','Not enough reputation'):tr('可以招募','Available to recruit')}</small></div><button disabled={locked||p.chapter<(r.minChapter??0)||view.cash<r.cost||view.reputation<r.reputation} onClick={()=>life('recruit',r.character)}>{tr('招募','Recruit')}</button></article>)}</div></details>
 <details class="management-card"><summary>{tr('硬件与软件','Hardware and software')}</summary><div class="management-list">{Object.entries(p.hardware).filter(([id])=>id!=='office'||!view.office).map(([id,level])=><article class="management-row" key={id}><div><b>{tr(({office:'办公',compute:'算力',storage:'存储',network:'网络'} as Record<string,string>)[id]!,id)} Lv.{level}</b><small>{level>=catalog.maxHardware?tr('已达等级上限','Maximum level reached'):locked?tr('请先处理当前状态','Resolve the current state first'):tr('升级费用见右侧按钮','Upgrade price shown on the button')}</small></div><button disabled={locked||level>=catalog.maxHardware} onClick={()=>life('hardware',id)}>{tr('升级','Upgrade')} ¥{[600,1800,4500,10000,24000][level]??'—'}</button></article>)}{catalog.software.map(u=><article class="management-row" key={u.id}><div><b>{english?u.nameEn:u.name}</b><small>¥{u.cost} / {u.research} RP · {tr('前置','Requires')}: {u.requires.join(', ')||'—'}</small>{locked&&<small>{tr('请先处理当前状态','Resolve the current state first')}</small>}</div><button disabled={locked||p.software.includes(u.id)} onClick={()=>life('software',u.id)}>{p.software.includes(u.id)?tr('已安装','Installed'):tr('研发','Research')}</button></article>)}</div></details>
 <details class="management-card"><summary>{tr('SLA维护','SLA maintenance')}</summary>{!p.incidents.some(i=>!i.resolved&&i.at<=view.absoluteSlot+(p.software.includes('monitor')?1:0))&&<p class="management-caption">{tr('当前没有待响应的维护事件。','No maintenance incidents need a response.')}</p>}{p.incidents.filter(i=>!i.resolved&&i.at<=view.absoluteSlot+(p.software.includes('monitor')?1:0)).map(i=><article class="management-row" key={i.job}><div><b>{i.job}</b><small>{tr('响应截止槽','Response deadline slot')} {i.deadline} · {tr('忙碌伙伴或尚未发生的事件不可响应。','Busy teammates and future incidents cannot respond yet.')}</small><div class="button-row">{view.actors.map(a=><button disabled={locked||a.busy||view.absoluteSlot<i.at} onClick={()=>void send({type:'respond',job:i.job,character:a.id})}>{names[a.id]}</button>)}</div></div></article>)}</details>
 <details class="management-card"><summary>{tr('资源方案与贷款','Resources and loans')}</summary><p>{tr('临购0.5元/T，跨日保留；订阅增加每日额度，按剩余周预付升级差价；本地需硬件投入，周结另付0.1元/算力。','Purchased tokens cost ¥0.5/T and carry over. Subscriptions add daily quota; upgrades prepay the remaining week. Local compute requires hardware and ¥0.1/unit electricity.')}</p><div class="button-row"><button disabled={locked} onClick={()=>void send({type:'buy',amount:100})}>{tr('买100T ¥50','Buy 100T ¥50')}</button>{[0,1,2].map(n=><button aria-pressed={p.subscription===n} disabled={locked||p.subscription===n} onClick={()=>life('subscribe',String(n))}>{tr('订阅','Plan')} {n}: +{[0,120,300][n]}T/{tr('天','day')} ¥{[0,120,420][n]}/{tr('周','week')}{p.subscription===n?tr(' · 当前',' · Current'):''}</button>)}<button disabled={locked} onClick={()=>void send({type:'loan',amount:1000})}>{tr('借1000元，周息5%','Borrow ¥1000; 5% weekly')}</button><button disabled={locked||view.loan<=0} onClick={()=>void send({type:'repay',amount:Math.min(1000,view.loan)})}>{tr('还款','Repay')} ¥{Math.min(1000,view.loan)}</button></div><small>{locked?tr('请先处理当前状态。','Resolve the current state first.'):view.loan<=0?tr('当前无待还贷款；当前订阅无需重复选择。','No loan to repay. The current plan is already selected.'):tr('当前订阅无需重复选择。','The current plan is already selected.')}</small></details>
 </div>}
 {panel==='journal'&&<div class="management-content journal-content"><nav class="management-tabs" aria-label={tr('手账栏目','Journal sections')}>{(['overview','projects','future','ledger'] as const).map((id,i)=><button key={id} aria-pressed={journalTab===id} aria-controls="journal-content" onClick={()=>setJournalTab(id)}>{[tr('概览','Overview'),tr('项目','Projects'),tr('明天','Tomorrow'),tr('收支','Ledger')][i]}</button>)}</nav><section id="journal-content" aria-label={tr('手账内容','Journal content')}>
 {journalTab==='overview'&&<section class="management-card"><h3>{tr('工作室近况','Studio overview')}</h3><p>{tr('第','Chapter ')} {p.chapter} · {chapterTitles[p.chapter]}</p><ul class="chapter-goals">{view.chapterGoal.requirements.map(r=><li key={r.label}>{r.met?'✓':'○'} {tr(r.label,r.labelEn)} · {r.current.toFixed(Number.isInteger(r.current)?0:2)} / {r.target}</li>)}</ul><small>{tr('伙伴故事在角色详情中阅读。游戏 Token 不调用真实 API。','Read stories in teammate profiles. Game tokens use no real API.')}</small></section>}
 {journalTab==='projects'&&<ProjectPanel view={view} english={english} busy={locked} send={send} openJob={setJobId}/>}
 {journalTab==='future'&&<><p class="management-caption">{tr('竞标第2章、远征第3章开放；完成第4章后选择结局。','Bids unlock in chapter 2, expeditions in chapter 3, and endings after chapter 4.')}</p><FinalePanel view={view} english={english} busy={locked} send={send}/></>}
 {journalTab==='ledger'&&<section class="management-card"><h3>{tr('最近收支','Recent transactions')}</h3>{view.ledger.length===0&&<p class="management-caption">{tr('还没有收支记录。','No transactions yet.')}</p>}{view.ledger.map((row,i)=><div class="ledger-row" key={i}><span>{tr('时段','Period')} {row.slot} · {ledgerLabel(row.reason,english)}</span><b>¥{row.amount.toFixed(2)}</b></div>)}</section>}
 </section></div>}
"""+s[end:]
# Requirement rows have no stable id field; use their existing label.
s=s.replace('key={r.id??r.label}','key={r.label}')
p.write_text(s,encoding='utf-8',newline='\n')
